import 'package:flutter/material.dart';
import 'package:shared_preferences/shared_preferences.dart';

class AppLanguage {
  const AppLanguage(this.code, this.label, this.flag);

  final String code;
  final String label;
  final String flag;
}

class AppLanguageService {
  AppLanguageService._();

  static final instance = AppLanguageService._();
  static const _storageKey = 'app_language_code';

  static const languages = <AppLanguage>[
    AppLanguage('system', 'Язык устройства', '🌐'),
    AppLanguage('ru', 'Русский', '🇷🇺'),
    AppLanguage('uk', 'Українська', '🇺🇦'),
    AppLanguage('en', 'English', '🇬🇧'),
    AppLanguage('de', 'Deutsch', '🇩🇪'),
    AppLanguage('fr', 'Français', '🇫🇷'),
    AppLanguage('es', 'Español', '🇪🇸'),
    AppLanguage('pt', 'Português', '🇵🇹'),
    AppLanguage('pl', 'Polski', '🇵🇱'),
    AppLanguage('tr', 'Türkçe', '🇹🇷'),
    AppLanguage('ar', 'العربية', '🇸🇦'),
    AppLanguage('hi', 'हिन्दी', '🇮🇳'),
    AppLanguage('zh', '中文', '🇨🇳'),
    AppLanguage('ja', '日本語', '🇯🇵'),
  ];

  final ValueNotifier<String> code = ValueNotifier('system');

  Future<void> initialize() async {
    final preferences = await SharedPreferences.getInstance();
    final saved = preferences.getString(_storageKey) ?? 'system';
    code.value = languages.any((language) => language.code == saved)
        ? saved
        : 'system';
  }

  Future<void> select(String value) async {
    if (!languages.any((language) => language.code == value)) return;
    code.value = value;
    final preferences = await SharedPreferences.getInstance();
    await preferences.setString(_storageKey, value);
  }

  Locale? get locale => code.value == 'system' ? null : Locale(code.value);

  String text(String key) {
    final selected = code.value == 'system'
        ? WidgetsBinding.instance.platformDispatcher.locale.languageCode
        : code.value;
    final translations =
        _authTranslations[selected] ?? _authTranslations['en']!;
    return translations[key] ?? _authTranslations['en']![key] ?? key;
  }

