      'e2eeInviteText': '{user} предлагает включить E2EE. После принятия сервер не сможет читать текст, фото, видео, файлы и голосовые сообщения. Звонки и группы пока не защищены.',
      'e2eeInviteSent': 'Приглашение E2EE отправлено. Ожидаем ответ.',
