      'e2eeDisableAction': 'Выключить',
      'e2eeBeforeTitle': 'Что такое защищённый чат?',
      'e2eeBeforeText': 'Текст и вложения закрываются на замок прямо на вашем устройстве и открываются только на устройстве собеседника. Сервер передаёт их, но прочитать текст или открыть вложение не может.\n\nЗащита включится только после согласия собеседника.\n\nДля дополнительной уверенности вы сможете сравнить одинаковый 60-значный код. Это как номер защитной пломбы между двумя устройствами.\n\nЗащищаются текст, фото, видео, файлы и голосовые сообщения в личном чате. Звонки и группы пока не защищены. FENYVO AI и перевод не смогут читать защищённый текст.',
      'e2eeNotNow': 'Не сейчас',
      'e2eeKeyChangedTitle': 'Код безопасности изменился',
      'e2eeKeyChangedText': 'Возможно, {user} сменил телефон или переустановил приложение. Это не обязательно означает опасность.\n\nЗащищённый чат продолжает работать, но прежняя отметка проверки снята. Для уверенности сравните новый 60-значный код.',
      'e2eeVerifyNewCode': 'Проверить новый код',
      'e2eeContinueUnverified': 'Продолжить без проверки',
      'e2eeVerifyTitle': 'Проверить защиту E2EE',
      'e2eeVerifyExplanation': 'Сравните этот код с кодом у {user}: все 60 цифр должны полностью совпасть. Лучше сравнить лично или во время звонка. QR-код содержит тот же номер безопасности.',
      'e2eeCodesMatch': 'Коды совпадают',
      'e2eeVerified': 'Ключ собеседника проверен',
      'e2eeVerifyNeedsMessage':
