      'e2eeVerifyError': 'Не удалось показать код безопасности.',
      'e2eeExplanation': 'Простыми словами: текст и вложения закрываются на вашем устройстве и открываются только на устройстве собеседника. Сервер получает бессмысленный шифр: он не может прочитать текст или открыть файл.\n\nПосле включения отправьте приглашение из меню нужного чата. Защита начнёт работать только после согласия собеседника. Защищаются текст, фото, видео, файлы и голосовые сообщения в личном чате. FENYVO AI и перевод не смогут читать защищённый текст. Звонки и группы пока не защищены.',
