      'e2eeDisableAction': 'Вимкнути',
      'e2eeBeforeTitle': 'Що таке захищений чат?',
      'e2eeBeforeText': 'Текст і вкладення закриваються на замок прямо на вашому пристрої та відкриваються лише на пристрої співрозмовника. Сервер передає їх, але не може прочитати текст або відкрити вкладення.\n\nЗахист увімкнеться лише після згоди співрозмовника.\n\nДля додаткової впевненості ви зможете порівняти однаковий 60-значний код. Це як номер захисної пломби між двома пристроями.\n\nЗахищаються текст, фото, відео, файли та голосові повідомлення в особистому чаті. Дзвінки й групи поки не захищені. FENYVO AI і переклад не зможуть читати захищений текст.',
