      'e2eeBeforeText': 'Text and attachments are locked on your device and opened only on the other person’s device. The server delivers them but cannot read the text or open an attachment.\n\nProtection starts only after the other person agrees.\n\nFor extra confidence, you can compare the same 60-digit code. Think of it as the number on a security seal between the two devices.\n\nPrivate-chat text, photos, videos, files, and voice messages are protected. Calls and groups are not protected yet. FENYVO AI and translation cannot read protected text.',
